// ── CONFIG ──────────────────────────────────────────────────────
// Cada usuário tem uma CHAVE (vai embutida no atalho do celular),
// o próprio token de API e o projeto de captura privado dele.
// TODO: preencher token real (VPS: docker exec plane-be-api-1 python
//       manage.py shell -c "from plane.db.models import APIToken;
//       print(APIToken.objects.get(label='n8n-captura').token)")
const USUARIOS = {
  'ana-2f8k': {
    nome: 'Ana Beatriz',
    token: 'TODO_plane_api_...',
    projeto: '1a84be32-f826-4a28-a99c-4f17cf36c20e'
  }
};
const SEGREDO = 'TODO_segredo_compartilhado_do_webhook';
// ────────────────────────────────────────────────────────────────

const body = $input.first().json.body || {};
if (body.segredo !== SEGREDO) {
  throw new Error('Segredo inválido');
}
const u = USUARIOS[body.chave];
if (!u) throw new Error('Chave de usuário desconhecida');
const texto = (body.texto || '').trim();
if (!texto) throw new Error('Texto vazio');

const hora = new Date().toLocaleTimeString('pt-BR', {
  timeZone: 'America/Sao_Paulo', hour: '2-digit', minute: '2-digit'
});
return [{ json: {
  token: u.token,
  projeto: u.projeto,
  titulo: texto.length > 120 ? texto.slice(0, 117) + '…' : texto,
  descricao: `<p>${texto}</p><p><em>Capturado pelo atalho • ${hora}</em></p>`
}}];
